const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const WEEK = 7 * 24 * HOUR;

class InMemoryIdeas implements RecipeIdeaRepository {
  readonly byId = new Map<RecipeIdeaId, RecipeIdea>();
  async get(id: RecipeIdeaId) {
    return this.byId.get(id) ?? null;
  }
  async save(idea: RecipeIdea) {
    this.byId.set(idea.id, idea);
  }
  async remove(id: RecipeIdeaId) {
    this.byId.delete(id);
  }
  async listAll() {
    return [...this.byId.values()];
  }
}

class InMemoryResearchRequests implements ResearchRequestLog {
  readonly all: ResearchRequest[] = [];
  async add(request: ResearchRequest) {
    this.all.push(request);
  }
  async listSince(from: number) {
    return this.all.filter((r) => r.requestedAt >= from);
  }
}

type ResearchQuery = Parameters<IdeaResearcher["research"]>[0];

/** The inspiration link, read under the safe-fetch rules: records what it was asked to read. */
class FakeInspiration implements InspirationReader {
  readonly read: string[] = [];
  text: string | null = "Kürbis aus dem Ofen, mit Salbei";
  async readInspiration(address: string) {
    this.read.push(address);
    return this.text;
  }
}

/** The research model: records what it was told, answers what the test says. */
class FakeResearcher implements IdeaResearcher {
  readonly asked: ResearchQuery[] = [];
  answer: (query: ResearchQuery) => Promise<unknown> = async () => ({
    candidates: [
      { title: "Kürbisgnocchi mit Salbei", link: "https://example.org/gnocchi", summary: "Mit Salbeibutter" },
      { title: "Ofenkürbis", link: "https://example.org/ofen", summary: "Schnell" },
    ],
  });
  async research(query: ResearchQuery) {
    this.asked.push(query);
    return this.answer(query);
  }
}

/** The import's ReadRecipe: records the sources it was handed. */
class FakeDraftImport implements Pick<DraftRecipeImport, "execute"> {
  readonly read: { member: string; address?: string; text?: string }[] = [];
  result: Result<RecipeDraft> = { ok: true, value: { name: "Kürbisgnocchi" } as RecipeDraft };
  async execute(cmd: { member: RecipeIdea["addedBy"]; address?: string; text?: string }) {
    this.read.push(cmd);
    return this.result;
  }
}

function ideas(config: IdeaConfig = defaultIdeaConfig) {
  const repo = new InMemoryIdeas();
  const requests = new InMemoryResearchRequests();
  const researcher = new FakeResearcher();
  const inspiration = new FakeInspiration();
  const draft = new FakeDraftImport();
  const clock = new FakeClock();
  const ids = new SequenceIds();
  return {
    repo,
    requests,
    researcher,
    inspiration,
    draft,
    clock,
    note: new NoteIdea({ ideas: repo, clock, ids }),
    edit: new EditIdea({ ideas: repo, clock }),
    list: new ListIdeas({ ideas: repo, clock }, config),
    research: new ResearchIdea({ ideas: repo, requests, researcher, inspiration, clock }, config),
    pick: new PickCandidate({ ideas: repo, clock, draft }),
    own: new UseOwnRecipe({ ideas: repo, clock, draft }),
    keep: new KeepIdea({ ideas: repo, clock }, config),
    remove: new DeleteIdea({ ideas: repo }),
  };
}

const must = <T>(r: Result<T>): T => {
  if (!r.ok) throw new Error(`rejected: ${r.reason}`);
  return r.value;
};

/** Moves the fake clock forward by whole hours (it counts in hours of a day). */
const advance = (clock: FakeClock, ms: number) => {
  const target = clock.now() + ms;
  const d = new Date(target);
  clock.date = d.toISOString().slice(0, 10) as FakeClock["date"];
  clock.hour = d.getUTCHours();
  expect(clock.now()).toBe(target);
};

