describe("ResearchIdea and ReplaceCandidates", () => {
  it("gives the model the idea's title, note and inspiration page, and replaces the candidates with what it found", async () => {
    const h = ideas();
    const idea = must(
      await h.note.execute({
        member: ME,
        title: "etwas mit Kürbis",
        note: "Hokkaido",
        inspirationLink: "https://i.org",
      }),
    );
    advance(h.clock, HOUR);
    const researched = must(await h.research.execute({ member: AC, idea: idea.id }));
    expect(h.inspiration.read).toEqual(["https://i.org"]);
    expect(h.researcher.asked).toEqual([
      { title: "etwas mit Kürbis", note: "Hokkaido", inspiration: "Kürbis aus dem Ofen, mit Salbei" },
    ]);
    expect(researched.candidates.map((c) => c.link)).toEqual([
      "https://example.org/gnocchi",
      "https://example.org/ofen",
    ]);
    expect(researched.lastTouchedAt).toBe(h.clock.now());
    expect(await h.repo.get(idea.id)).toEqual(researched);
    expect(h.requests.all).toEqual([{ requestedBy: AC, requestedAt: h.clock.now() }]);
  });

  it("replaces the earlier candidates on a new research", async () => {
    const h = ideas();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    must(await h.research.execute({ member: ME, idea: idea.id }));
    h.researcher.answer = async () => ({
      candidates: [{ title: "Kürbissuppe", link: "https://example.org/suppe", summary: "" }],
    });
    const again = must(await h.research.execute({ member: ME, idea: idea.id }));
    expect(again.candidates.map((c) => c.title)).toEqual(["Kürbissuppe"]);
  });

  it("drops candidates beyond the maximum and those without an http(s) link", async () => {
    const h = ideas({ ...defaultIdeaConfig, maxCandidates: 2 });
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    h.researcher.answer = async () => ({
      candidates: [
        { title: "bad", link: "javascript:alert(1)", summary: "" },
        { title: "a", link: "https://example.org/a", summary: "" },
        { title: "b", link: "https://example.org/b", summary: "" },
        { title: "c", link: "https://example.org/c", summary: "" },
      ],
    });
    const researched = must(await h.research.execute({ member: ME, idea: idea.id }));
    expect(researched.candidates.length).toBeLessThanOrEqual(2);
    expect(researched.candidates.every((c) => c.link.startsWith("https://"))).toBe(true);
    expect(researched.candidates.map((c) => c.title)).not.toContain("bad");
  });

  it("changes nothing when the answer brings no usable candidate: the idea keeps its candidates and clock", async () => {
    const h = ideas();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    const first = must(await h.research.execute({ member: ME, idea: idea.id }));
    advance(h.clock, HOUR);
    for (const answer of [
      { candidates: [] },
      "Sorry!",
      { candidates: [{ title: "x", link: "ftp://a", summary: "" }] },
    ]) {
      h.researcher.answer = async () => answer;
      expect(await h.research.execute({ member: ME, idea: idea.id })).toEqual({ ok: false, reason: "nothing_found" });
      expect(await h.repo.get(idea.id)).toEqual(first);
    }
    // Only the first, useful research counts against the limit.
    expect(h.requests.all).toHaveLength(1);
  });

  it("changes nothing when the model fails, tells that nothing was found, and the attempt does not count", async () => {
    const h = ideas();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    h.researcher.answer = async () => {
      throw new Error("503");
    };
    expect(await h.research.execute({ member: ME, idea: idea.id })).toEqual({ ok: false, reason: "nothing_found" });
    expect(await h.repo.get(idea.id)).toEqual(idea);
    expect(h.requests.all).toEqual([]);
  });

  it("tells when research is not set up", async () => {
    const h = ideas();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    h.researcher.answer = async () => {
      throw new ResearchNotConfigured();
    };
    expect(await h.research.execute({ member: ME, idea: idea.id })).toEqual({ ok: false, reason: "not_configured" });
    expect(await h.repo.get(idea.id)).toEqual(idea);
  });

  it("refuses a member who asked as often as the hourly limit allows, without asking the model", async () => {
    const h = ideas({ ...defaultIdeaConfig, maxResearchPerHour: 2 });
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    must(await h.research.execute({ member: ME, idea: idea.id }));
    must(await h.research.execute({ member: ME, idea: idea.id }));
    expect(await h.research.execute({ member: ME, idea: idea.id })).toEqual({ ok: false, reason: "rate_limited" });
    expect(h.researcher.asked).toHaveLength(2);
    expect(h.requests.all).toHaveLength(2);
    // The other member has a limit of their own.
    expect((await h.research.execute({ member: AC, idea: idea.id })).ok).toBe(true);
    // An hour later the member may ask again.
    advance(h.clock, HOUR);
    expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(true);
  });

  it("uses the default limit of 20 per member and hour", async () => {
    const h = ideas();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    for (let i = 0; i < 20; i++) expect((await h.research.execute({ member: ME, idea: idea.id })).ok).toBe(true);
    expect(await h.research.execute({ member: ME, idea: idea.id })).toEqual({ ok: false, reason: "rate_limited" });
  });

  it("says when the idea is gone, and asks nobody", async () => {
    const h = ideas();
    expect(await h.research.execute({ member: ME, idea: recipeIdeaId("gone") })).toEqual({
      ok: false,
      reason: "idea_not_found",
    });
    expect(h.researcher.asked).toEqual([]);
  });

  it("does not bring back an idea deleted while the model worked", async () => {
    const h = ideas();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    const answer = h.researcher.answer;
    h.researcher.answer = async (q) => {
      await h.remove.execute({ member: AC, idea: idea.id });
      return answer(q);
    };
    const r = await h.research.execute({ member: ME, idea: idea.id });
    expect(r.ok).toBe(false);
    expect(await h.repo.get(idea.id)).toBeNull();
    // The research brought candidates, so it counts all the same (CountUsefulResearch).
    expect(h.requests.all).toEqual([{ requestedBy: ME, requestedAt: h.clock.now() }]);
  });

  it("keeps an edit made while the model worked", async () => {
    const h = ideas();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    const answer = h.researcher.answer;
    h.researcher.answer = async (q) => {
      await h.edit.execute({ member: AC, idea: idea.id, title: "Kürbisgnocchi", note: "neu" });
      return answer(q);
    };
    const researched = must(await h.research.execute({ member: ME, idea: idea.id }));
    expect(researched).toMatchObject({ title: "Kürbisgnocchi", note: "neu" });
    expect(researched.candidates).toHaveLength(2);
    expect(await h.repo.get(idea.id)).toEqual(researched);
  });
});

describe("PickCandidate", () => {
  it("starts the import with the candidate's link and moves the idea's clock", async () => {
    const h = ideas();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    must(await h.research.execute({ member: ME, idea: idea.id }));
    advance(h.clock, 3 * HOUR);
    const r = await h.pick.execute({ member: AC, idea: idea.id, candidate: 1 });
    expect(r).toEqual(h.draft.result);
    expect(h.draft.read).toEqual([{ member: AC, address: "https://example.org/ofen" }]);
    expect((await h.repo.get(idea.id))?.lastTouchedAt).toBe(h.clock.now());
  });

  it("moves the clock even when the import refuses the link, and tells why it refused", async () => {
    const h = ideas();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    must(await h.research.execute({ member: ME, idea: idea.id }));
    advance(h.clock, 3 * HOUR);
    h.draft.result = { ok: false, reason: "address_not_public" };
    expect(await h.pick.execute({ member: ME, idea: idea.id, candidate: 0 })).toEqual({
      ok: false,
      reason: "address_not_public",
    });
    const after = await h.repo.get(idea.id);
    expect(after?.lastTouchedAt).toBe(h.clock.now());
    expect(after?.candidates).toHaveLength(2);
  });

  it("refuses a candidate the idea does not have, and an idea that is gone", async () => {
    const h = ideas();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    expect(await h.pick.execute({ member: ME, idea: idea.id, candidate: 0 })).toEqual({
      ok: false,
      reason: "no_such_candidate",
    });
    expect(await h.pick.execute({ member: ME, idea: recipeIdeaId("gone"), candidate: 0 })).toEqual({
      ok: false,
      reason: "idea_not_found",
    });
    expect(h.draft.read).toEqual([]);
  });
});

