describe("CreateImportedRecipe carrying an idea (ForgetRealisedIdea)", () => {
  const vocabulary: Vocabulary = { items: ["Kürbis"], tags: [] };
  const confirmed = () => ({
    name: "Kürbisgnocchi",
    steps: ["Kochen."],
    ingredients: [{ name: "Kürbis", amount: "500 g" }],
    mealType: "main",
    base: "other",
    diet: "vegetarian",
    tags: [],
    source: "https://example.org/gnocchi",
  });

  function withImport() {
    const h = ideas();
    const created: RecipeDraft[] = [];
    const writer: RecipeWriter = {
      vocabulary: async () => vocabulary,
      create: async (draft) => {
        created.push(draft);
        return { recipeId: 7, photoAttached: false };
      },
    };
    return { ...h, created, create: new CreateImportedRecipe({ writer, ideas: h.repo }) };
  }

  it("lets the idea and its candidates go once its recipe is created", async () => {
    const h = withImport();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbisgnocchi" }));
    must(await h.research.execute({ member: ME, idea: idea.id }));
    const r = await h.create.execute({ member: AC, draft: confirmed(), idea: idea.id });
    expect(r.ok && r.value.recipeId).toBe(7);
    expect(h.created).toHaveLength(1);
    expect(await h.repo.get(idea.id)).toBeNull();
  });

  it("creates the recipe all the same when the idea was deleted during the review", async () => {
    const h = withImport();
    const r = await h.create.execute({ member: ME, draft: confirmed(), idea: recipeIdeaId("gone") });
    expect(r.ok && r.value.recipeId).toBe(7);
    expect(h.created).toHaveLength(1);
  });

  it("creates the recipe like any other without an idea, and leaves the household's ideas alone", async () => {
    const h = withImport();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbisgnocchi" }));
    expect((await h.create.execute({ member: ME, draft: confirmed() })).ok).toBe(true);
    expect(await h.repo.get(idea.id)).toEqual(idea);
  });

  it("keeps the idea when the draft is refused, as no recipe was created", async () => {
    const h = withImport();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbisgnocchi" }));
    expect(await h.create.execute({ member: ME, draft: { ...confirmed(), ingredients: [] }, idea: idea.id })).toEqual({
      ok: false,
      reason: "not_a_recipe",
    });
    expect(h.created).toEqual([]);
    expect(await h.repo.get(idea.id)).toEqual(idea);
  });

  it("keeps the idea when KitchenOwl could not create the recipe", async () => {
    const h = ideas();
    const writer: RecipeWriter = {
      vocabulary: async () => vocabulary,
      create: async () => {
        throw new Error("500");
      },
    };
    const create = new CreateImportedRecipe({ writer, ideas: h.repo });
    const idea = must(await h.note.execute({ member: ME, title: "Kürbisgnocchi" }));
    expect(await create.execute({ member: ME, draft: confirmed(), idea: idea.id })).toEqual({
      ok: false,
      reason: "kitchenowl_unavailable",
    });
    expect(await h.repo.get(idea.id)).toEqual(idea);
  });
});
